mapper.select:
        select bm.*
		from hls_bp_master bm
		where bm.REGISTER_CERT_NUM = #{enterpriseUnifiedCreditCode,jdbcType=VARCHAR}

select bm.*
from hls_bp_master bm
where bm.ORGANIZATION_CODE = #{organizationCode,jdbcType=VARCHAR}

select hbm.* from hls_bp_master hbm

    1=1

        AND hbm.bp_id = #{bpId}


        AND hbm.bp_name = #{bpName}

SELECT hbm.*, hbt.description typedes, (select cb.bank_name from csh_bank cb where cb.bank_id=hbm.bank_id ) bank_name, hbc.description catedes FROM hls_bp_master hbm, hls_bp_master_role hbmr, hls_bp_type hbt, hls_bp_category hbc
hbm.bp_id = hbmr.bp_id AND hbt.bp_type = hbmr.bp_type AND hbc.bp_category = hbmr.bp_category AND hbmr.bp_category = 'CREDIT_ORGANIZATION' AND hbm.company_id=#{request.companyId}
and hbm.bp_id = #{bpId,jdbcType=BIGINT}
and hbm.bp_name LIKE concat(concat('%',#{bpName,jdbcType=VARCHAR}),'%')
ORDER BY hbm.bp_code DESC

select * from ( SELECT hbm.bp_id, hbm.bp_code, hbm.bp_name, hbm.extra_nam, ( select hbt.description from hls_bp_master_role mr, hls_bp_type hbt where mr.bp_id = hbm.bp_id and mr.enabled_flag = 'Y' and mr.bp_type = hbt.bp_type and rownum=1 ORDER BY mr.CREATION_DATE asc
) as bp_type, ( select mr.bp_type from hls_bp_master_role mr, hls_bp_type hbt where mr.bp_id = hbm.bp_id and mr.enabled_flag = 'Y' and mr.bp_type = hbt.bp_type and rownum=1 ORDER BY mr.CREATION_DATE asc
) as bp_type1, case hbm.bp_class when 'ORG' then '法人' else '自然人' end as bp_class, hbm.associated_division FROM hls_bp_master hbm where hbm.CREATED_BY = #{request.userId}) t1 where 1=1
and t1.bp_type1 in
#{item}
and t1.bp_class in
#{item}
and t1.bp_code like concat('%', #{bpCode}, '%')
and t1.bp_name like concat('%', #{bpFullName}, '%')
and t1.extra_nam like concat('%', #{bpName}, '%')
and t1.associated_division in
#{item}

select bm.bp_code
from hls_bp_master bm
where bm.Enterprise_unified_credit_code = #{enterpriseUnifiedCreditCode,jdbcType=VARCHAR}

select bm.bp_code
from hls_bp_master bm
where bm.id_card_no = #{idCardNo,jdbcType=VARCHAR}

SELECT DISTINCT(bm.bp_id), bm.bp_code, bm.bp_name, bm.bp_class, ( SELECT vb.description FROM sys_code_b cb, sys_code_value_b vb WHERE cb.CODE='FND.BP_CLASS' and vb.CODE_ID = cb.CODE_ID and vb.value = bm.bp_class ) bp_class_desc FROM hls_bp_master bm, hls_bp_master_role mr
bm.bp_id = mr.bp_id
and bm.bp_id = #{ bpId }
and bm.bp_name = #{ bpName }
and mr.bp_type = #{bpType} and mr.enabled_flag = 'Y'
and bm.bp_id in (select cct.tenant_bp_id from con_contract_tenant cct where cct.contract_id = #{contractId})

select *
from hls_bp_master bp


        bp.bp_id = #{ bpId }


        bp.bp_code = #{ bpCode }


        and bp.bp_name like concat(concat('%',#{ bpName }),'%')

SELECT DISTINCT (bm.bp_id), bm.bp_name, hur.user_id, v2.CREATION_DATE, ( SELECT bt.description FROM hls_bp_type bt WHERE v2.bp_type = bt.bp_type ) description,hur.RELATION_DOCUMENT_ID FROM
hls_user_relationship hur, hls_bp_master bm, ( SELECT v1.bp_id, v1.bp_type, v1.CREATION_DATE FROM ( SELECT mr.bp_id, mr.CREATION_DATE, mr.bp_type FROM hls_bp_master_role mr, hls_user_relationship hur
WHERE
hur.RELATION_DOCUMENT_ID = mr.bp_id and mr.enabled_flag='Y' AND mr.bp_category = 'CREDIT_ORGANIZATION' AND hur.RELATION_DOCUMENT_CATEGORY='HLS_BP_MASTER' AND hur.RELATION_TYPE='P2D' AND hur.source_event='HLS_BP_MASTER.COLLECT' ORDER BY mr.CREATION_DATE ) v1 GROUP BY v1.bp_id, v1.bp_type , v1.CREATION_DATE ) v2 WHERE bm.bp_id = hur.RELATION_DOCUMENT_ID AND hur.RELATION_DOCUMENT_ID = v2.bp_id AND bm.enabled_flag = 'Y' AND bm.company_id=#{request.companyId}
AND user_id = #{userId}
AND hur.RELATION_DOCUMENT_CATEGORY = #{bpCategory}
ORDER BY hur.RELATION_DOCUMENT_ID DESC

SELECT * FROM ( SELECT DISTINCT v.*, (case when hur.RELATION_DOCUMENT_ID is null then 'N' else 'Y' end) collectFlag from (SELECT bm.bp_id, bm.bp_class, bm.CREATION_DATE, bm.bp_code, bm.bp_name, bm.org_type, bm.company_id, bm.CREATED_BY, ( SELECT bt.description FROM hls_bp_type bt WHERE mr.bp_type = bt.bp_type ) description, ( SELECT bt.bp_category FROM hls_bp_type bt WHERE mr.bp_type = bt.bp_type ) bp_category FROM hls_bp_master bm, hls_bp_master_role mr where bm.bp_id = mr.bp_id AND bm.enabled_flag = 'Y' AND mr.enabled_flag = 'Y'
and mr.bp_type = #{bpType}
) v LEFT JOIN hls_user_relationship hur on v.bp_id = hur.RELATION_DOCUMENT_ID and hur.user_id = #{userId} AND hur.RELATION_DOCUMENT_CATEGORY='HLS_BP_MASTER' AND hur.RELATION_TYPE='P2D' AND hur.source_event='HLS_BP_MASTER.COLLECT' )bp
bp.bp_category = 'CREDIT_ORGANIZATION'
bp.bp_category != 'CREDIT_ORGANIZATION'
and bp.company_id = #{request.companyId}
and bp.description like concat(concat('%',#{bpTypeDesc}),'%')
and EXISTS (select 1 from sys_code_b scb, sys_code_value_b scvb where scb.CODE_ID = scvb.CODE_ID and scb.CODE='CSH.BANK_ORG_TYPE' and scvb.VALUE = bp.org_type and (scvb.MEANING like concat(concat('%',#{orgTypeDesc}),'%') or scvb.DESCRIPTION like concat(concat('%',#{orgTypeDesc}),'%')))
and (bp.bp_name like concat(concat('%',#{bpName}),'%') or bp.bp_code like concat(concat('%',#{bpName}),'%'))
order by bp.CREATION_DATE desc

(SELECT bp.bp_id,bp.bp_name,bp.tax_registry_num,bp.invoice_bp_bank_account,bp.invoice_bp_address_phone_num
FROM
con_contract_cashflow ccc,hls_bp_master bp,con_contract_tenant cct

    cct.tenant_bp_id = bp.bp_id
    AND ccc.contract_id = cct.contract_id

        AND ccc.cashflow_id = #{docId}


        AND 'CASHFLOW'=#{groupByFlag}


)
UNION
(SELECT bp.bp_id,bp.bp_name,bp.tax_registry_num,bp.invoice_bp_bank_account,bp.invoice_bp_address_phone_num
FROM
hls_bp_master bp


        bp.bp_id = #{docId}


        AND 'BP'=#{groupByFlag}


)
UNION
(SELECT bp.bp_id,bp.bp_name,bp.tax_registry_num,bp.invoice_bp_bank_account,bp.invoice_bp_address_phone_num
FROM
hls_bp_master bp,con_contract_tenant cct
cct.tenant_bp_id = bp.bp_id

        AND cct .contract_id = #{docId}

    AND 'CONTRACT'=#{groupByFlag}


)

SELECT temp.* FROM ( SELECT m.bp_name, m.bp_code, m.bp_id, m.bp_class, m.associated_division, r.bp_type, ( select t.description from hls_bp_type t where t.bp_type = r.bp_type )as bp_type_desc, r.bp_category, (SELECT scv.DESCRIPTION FROM sys_code_b scb, sys_code_value_b scv WHERE scb. CODE = 'FND.ENTERPRISE_LEGAL_FORM' AND scb.CODE_ID = scv.CODE_ID AND scv.VALUE = m.legal_form) AS legal_form, m.legal_representative, registered_place FROM hls_bp_master m,hls_bp_master_role r
1=1 and m.bp_id = r.bp_id
AND m.bp_id = #{bpId}
AND r.bp_type = #{bpType}
AND r.bp_category = #{bpCategory}
AND m.bp_name like concat('%',concat(#{bpName},'%'))
AND m.bp_code like concat('%',concat(#{bpCode},'%'))
) temp WHERE 1=1
AND temp.legal_form like concat('%',concat(#{legalForm},'%'))

SELECT tt.bp_id, tt.bp_name, tt.BP_ENG_NAME, wm_concat(tt.description) AS description, tt.BP_CODE, CASE WHEN tt.BP_CLASS = 'ORG' THEN '法人' WHEN tt.BP_CLASS = 'NP' THEN '自然人' ELSE tt.BP_CLASS END as BP_CLASS, tt.EXTRA_NAM, to_char(tt.CREATION_DATE,'YYYY-MM-DD') CREATION_DATE_STR, tt.NAME, tt.UNIT_NAME FROM (SELECT DISTINCT bm.bp_id, bm.bp_name, bm.BP_ENG_NAME, bm.BP_CODE, bm.BP_CLASS, bm.EXTRA_NAM, bm.CREATION_DATE, TABALL.NAME, TABALL.UNIT_NAME, CASE WHEN bm.ASSOCIATED_DIVISION IS NULL THEN 'N' ELSE bm.ASSOCIATED_DIVISION END AS ASSOCIATED_DIVISION, ( SELECT bt.description FROM hls_bp_type bt WHERE mr.bp_type = bt.bp_type ) description FROM hls_bp_master bm, (SELECT FE.NAME,SUA.USER_ID,MIN(FOU.UNIT_NAME) UNIT_NAME,SUA.COMPANY_ID FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID=FOU.UNIT_ID, (SELECT MIN(COMPANY_ID) COMPANY_ID,USER_ID FROM SYS_USER_ALLOCATION GROUP BY USER_ID ORDER BY USER_ID ASC ) SUAC, FND_EMPLOYEE FE WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.COMPANY_ID = SUAC.COMPANY_ID AND SUA.USER_ID = SUAC.USER_ID AND FE.EMPLOYEE_ID = FEA.EMPLOYEE_ID GROUP BY SUA.USER_ID,SUA.COMPANY_ID,FE.NAME ORDER BY SUA.USER_ID ASC) TABALL, ( SELECT DISTINCT hbmr.bp_id, hbmr.bp_type, hbmr.CREATION_DATE, hbmr.enabled_flag, hbmr.bp_category FROM hls_bp_master_role hbmr
AND hbmr.bp_type IN (#{map.bpType})
ORDER BY CREATION_DATE ASC ) mr WHERE bm.bp_id = mr.bp_id AND bm.enabled_flag = 'Y' AND mr.enabled_flag = 'Y' AND mr.bp_category != 'CREDIT_ORGANIZATION' AND bm.CREATED_BY = TABALL.USER_ID ORDER BY bm.bp_name ASC) tt
AND tt.bp_name = #{map.bpName}
AND tt.bp_code = #{map.bpCode}
AND tt.EXTRA_NAM = #{map.extraNam}
AND tt.bp_class IN (#{map.bpClass})
AND tt.associated_division IN (#{map.associatedDivision})
GROUP BY tt.bp_id, tt.bp_name, tt.BP_ENG_NAME, tt.BP_CODE, tt.BP_CLASS, tt.EXTRA_NAM, tt.CREATION_DATE, tt.NAME, tt.UNIT_NAME ORDER BY tt.CREATION_DATE DESC

select * from ( select hm.bp_id, hm.bp_name, hm.credit_type, to_char(hm.valid_from,'yyyy-mm-dd hh24:mi:ss') valid_from, to_char(hm.valid_to,'yyyy-mm-dd hh24:mi:ss') valid_to, hm.credit_line_amount, nvl(HLS_CREDUT_LINE_CALC.credit_Used_Amt_clac(hm.bp_id),0) credit_used_amount, nvl(HLS_CREDUT_LINE_CALC.credit_Exposure_Amt(hm.bp_id),0) credit_exposure_amount, nvl(HLS_CREDUT_LINE_CALC.credit_preemption_Amt(hm.bp_id),0) credit_preemption_amount, (select t1.meaning from sys_code_b t, sys_code_value_b t1 where t.code_id = t1.code_id and t.code = 'FCT.CREDIT_TYPE' and t1.value=hm.credit_type)credit_type_desc from hls_bp_master hm where not exists(select * from HLS_BP_MASTER_ROLE hr where hm.BP_ID = hr.BP_ID and hr.BP_CATEGORY = 'CREDIT_ORGANIZATION')) tg
and tg.bp_name like concat('%', concat(#{bpName}, '%'))
and tg.credit_type_desc like concat('%', concat(#{creditTypeDesc}, '%'))
and tg.credit_type = #{creditType}
and tg.credit_line_amount >= #{limitFrom}
and tg.credit_line_amount <= #{limitTo}
and tg.VALID_FROM >= #{beginDate}
and tg.VALID_TO <= #{endDate}

select
count(1)
from hls_bp_master hbm
where hbm.bp_name = #{bpName}

    and hbm.bp_id != #{bpId}

SELECT temp.* FROM ( SELECT m.bp_name, m.bp_code, m.bp_id, r.bp_type, ( select t.description from hls_bp_type t where t.bp_type = r.bp_type )as bp_type_desc, r.bp_category, (SELECT scv.DESCRIPTION FROM sys_code_b scb, sys_code_value_b scv WHERE scb. CODE = 'FND.ENTERPRISE_LEGAL_FORM' AND scb.CODE_ID = scv.CODE_ID AND scv.VALUE = m.legal_form) AS legal_form, m.legal_representative, registered_place FROM hls_bp_master m,hls_bp_master_role r
1=1 and m.bp_id = r.bp_id and r.bp_category = 'CREDIT_ORGANIZATION'
AND m.bp_id = #{bpId}
AND r.bp_type = #{bpType}
AND m.org_type = #{orgType}
AND r.bp_category = #{bpCategory}
AND m.bp_name like concat('%',concat(#{bpName},'%'))
AND m.bp_code like concat('%',concat(#{bpCode},'%'))
) temp WHERE 1=1
AND temp.legal_form like concat('%',concat(#{legalForm},'%'))

select ttt.*, CASE WHEN ttt.BP_CLASS = 'ORG' THEN '法人' WHEN ttt.BP_CLASS = 'NP' THEN '自然人' ELSE ttt.BP_CLASS END as BP_CLASS_N, (select sc.meaning from sys_code_value_b_v sc where sc.code = 'BP.BP_MASTER_ROLE' AND sc.CODE_VALUE = tttt.bp_type) description, (select c.country_name from fnd_country c where c.country = tttt.business_area) business_area_n, 'asda' as group_company_n, 'qwew' as visit_information, ( select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'FND.INDUSTRY_2' and sc.code_value = tttt.economic_indu_classify) AS economic_indu_classify_n from (SELECT tt.bp_id, tt.bp_name, tt.BP_ENG_NAME, -- wm_concat(tt.description) AS description, tt.BP_CODE, tt.BP_CLASS, tt.EXTRA_NAM, to_char(tt.CREATION_DATE, 'YYYY-MM-DD') AS CREATION_DATE_STR, tt.NAME, tt.UNIT_NAME, tt.ENABLED_FLAG, tt.business_area, tt.nationality_n, tt.UNIT_ID, tt.group_company_n, tt.group_company_prj_amount, tt.group_company_con_amount, tt.group_company_total_amount, -- tt.visit_information, -- tt.economic_indu_classify_n, -- tt.group_companies, -- tt.business_area_n FROM (SELECT DISTINCT bm.bp_id, bm.bp_name, bm.BP_ENG_NAME, bm.BP_CODE, bm.BP_CLASS, bm.EXTRA_NAM, bm.CREATION_DATE, bm.ENABLED_FLAG, TABALL.NAME, TABALL.UNIT_NAME, (select fou.unit_name from hls_marketing_report_bp hmrb, hls_marketing_report hmr, fnd_org_unit fou where hmrb.bp_id = bm.bp_id and hmrb.marketing_report_id = hmr.marketing_report_id and hmr.unit_id = fou.unit_id and hmrb.creation_date = (select max(hmrb2.creation_date) from hls_marketing_report_bp hmrb2 where hmrb2.bp_id = bm.bp_id) and hmr.STATUS = 'APPROVED' and rownum=1) unit_id, CASE WHEN bm.ASSOCIATED_DIVISION IS NULL THEN 'N' ELSE bm.ASSOCIATED_DIVISION END AS ASSOCIATED_DIVISION, (select sc.meaning from sys_code_value_b_v sc where sc.code = 'BP.BP_MASTER_ROLE' AND sc.CODE_VALUE = bm.bp_type) description, bm.business_area, (select sc.meaning from sys_code_value_b_v sc where sc.code = 'HLS211_NATIONALITY' and sc.code_value = bm.nationality) nationality_n, bm.bp_type, bm.economic_indu_classify, -- (select hsc.description from hls_stat_class hsc -- where hsc.class_id = bm.economic_indu_classify -- and hsc.enabled_flag = 'Y') economic_indu_classify_n,
nvl((select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'FND.INDUSTRY_2' and sc.code_value = bm.economic_indu_classify), (SELECT t.description FROM hls_stat_class t WHERE t.class_usage = 'BIZ_PARTNER' AND t.enabled_flag = 'Y' and to_char(t.CLASS_ID) = bm.economic_indu_classify))economic_indu_classify_n, (select c.country_name from fnd_country c where c.country = bm.business_area) business_area_n, 'asda' as group_company_n, ( SELECT sum(q.finance_amount) FROM prj_quotation q WHERE q.source_document_category = 'PRJ_PROJECT' AND q.data_class = 'PRJ_PROJECT_INVEST' AND q.source_document_id IN ( SELECT DISTINCT bp.project_id FROM hls_bp_master b, prj_project_bp bp WHERE b.group_companies = bm.group_companies AND b.bp_id = bp.bp_id AND b.bp_type IN ( 'TENANT', 'TENANT_SEC', 'ACCOUNTS_RECEIVABLE', 'ASSET_TRANSFEROR' ) ) ) group_company_prj_amount, ( SELECT SUM( q.finance_amount ) FROM prj_project q WHERE q.data_class = 'VIRTUAL_CON' and q.CONTRACT_STATUS not in('CANCEL','REJECTED','NEW') AND q.PROJECT_ID IN ( SELECT DISTINCT bp.project_id FROM hls_bp_master b, prj_project_bp bp WHERE b.group_companies = bm.group_companies AND b.bp_id = bp.bp_id AND b.bp_type IN ( 'TENANT', 'TENANT_SEC', 'ACCOUNTS_RECEIVABLE', 'ASSET_TRANSFEROR' ) ) ) AS group_company_con_amount, ( SELECT sum(c.due_amount) FROM con_contract_cashflow c WHERE c.cf_item = 0 AND c.write_off_flag = 'FULL' AND c.contract_id IN ( SELECT DISTINCT t.contract_id FROM prj_project_bp tb, con_contract t, hls_bp_master b WHERE b.group_companies = bm.group_companies AND tb.bp_type IN ( 'TENANT', 'TENANT_SEC', 'ACCOUNTS_RECEIVABLE', 'ASSET_TRANSFEROR' ) AND tb.bp_id = b.bp_id AND t.project_id = tb.project_id AND t.data_class = 'NORMAL' ) ) AS group_company_total_amount, 'qwew' as visit_information, bm.group_companies FROM hls_bp_master bm, (SELECT FE.NAME,SUA.USER_ID,MIN(FOU.UNIT_NAME) UNIT_NAME,SUA.COMPANY_ID FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID=FOU.UNIT_ID, (SELECT MIN(COMPANY_ID) COMPANY_ID,USER_ID FROM SYS_USER_ALLOCATION GROUP BY USER_ID ORDER BY USER_ID ASC ) SUAC, FND_EMPLOYEE FE WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.COMPANY_ID = SUAC.COMPANY_ID AND SUA.USER_ID = SUAC.USER_ID AND FE.EMPLOYEE_ID = FEA.EMPLOYEE_ID GROUP BY SUA.USER_ID,SUA.COMPANY_ID,FE.NAME ORDER BY SUA.USER_ID ASC) TABALL, ( SELECT DISTINCT hbmr.bp_id, hbmr.bp_type, hbmr.CREATION_DATE, hbmr.enabled_flag, hbmr.bp_category FROM hls_bp_master_role hbmr
AND hbmr.bp_type = #{bpType}
ORDER BY CREATION_DATE ASC ) mr WHERE bm.bp_id = mr.bp_id AND mr.bp_category != 'CREDIT_ORGANIZATION' AND bm.CREATED_BY = TABALL.USER_ID ORDER BY bm.bp_name ASC) tt
AND tt.bp_name LIKE concat(concat('%',#{bpName}),'%')
AND tt.bp_code LIKE concat(concat('%',#{bpCode}),'%')
AND tt.EXTRA_NAM LIKE concat(concat('%',#{extraNam}),'%')
AND tt.bp_class = #{bpClass}
AND tt.bp_type = #{bpType}
AND tt.name LIKE concat(concat('%',#{name}),'%')
AND tt.unit_name LIKE concat(concat('%',#{unitName}),'%')
AND tt.enabled_flag = #{enabledFlag}
AND tt.associated_division = #{associatedDivision}
AND tt.unit_id LIKE concat(concat('%',#{unitId}),'%')
GROUP BY tt.bp_id, tt.bp_name, tt.BP_ENG_NAME, tt.BP_CODE, tt.BP_CLASS, tt.EXTRA_NAM, tt.CREATION_DATE, tt.NAME, tt.UNIT_NAME, tt.ENABLED_FLAG, tt.UNIT_ID, tt.business_area, tt.nationality_n, tt.group_company_n, tt.group_company_prj_amount, tt.group_company_con_amount, tt.group_company_total_amount ORDER BY tt.CREATION_DATE DESC)ttt, hls_bp_master tttt where ttt.bp_id = tttt.bp_id

select * from ( SELECT bm.bp_id, bm.bp_name, bm.BP_ENG_NAME, bm.BP_CODE, bm.BP_CLASS, (SELECT hbt.description value_name FROM hls_business_type hbt WHERE hbt.document_category = 'HLS_BP_MASTER' AND hbt.business_type = bm.BP_CLASS) BP_CLASS_N, bm.EXTRA_NAM, bm.CREATION_DATE, bm.ENABLED_FLAG, bm.CREATED_BY, (SELECT s.description FROM SYS_USER s WHERE S.user_id=bm.created_by) NAME, (SELECT MIN(FOU.UNIT_NAME) FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID=FOU.UNIT_ID WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.USER_ID = bm.CREATED_BY) UNIT_NAME, (SELECT MIN(FOU.UNIT_ID) FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID=FOU.UNIT_ID WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.USER_ID = bm.CREATED_BY) unit_id, CASE WHEN bm.ASSOCIATED_DIVISION IS NULL THEN 'N' ELSE bm.ASSOCIATED_DIVISION END AS ASSOCIATED_DIVISION, (select sc.meaning from sys_code_value_b_v sc where sc.code = 'BP.BP_MASTER_ROLE' AND sc.CODE_VALUE = bm.bp_type) description, bm.business_area, (select sc.meaning from sys_code_value_b_v sc where sc.code = 'HLS211_NATIONALITY' and sc.code_value = bm.nationality) nationality_n, bm.bp_type, bm.economic_indu_classify, decode((select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'FND.INDUSTRY_2' and sc.code_value = bm.economic_indu_classify),null, (SELECT t.description FROM hls_stat_class t WHERE t.class_usage = 'BIZ_PARTNER' AND t.enabled_flag = 'Y' and to_char(t.CLASS_ID) = bm.economic_indu_classify)) economic_indu_classify_n, (select c.country_name from fnd_country c where c.country = bm.business_area) business_area_n, 'asda' as group_company_n, 'qwew' as visit_information, 'zxcx' AS change_record, bm.group_companies, to_char(bm.CREATION_DATE, 'yyyy-mm-dd') AS CREATION_DATE_STR, bm.retail_flag, bm.source, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'SOURCE' and sc.code_value = bm.source ) source_n FROM hls_bp_master bm WHERE bm.BP_APPROVE_STATUS is null or bm.BP_APPROVE_STATUS='APPROVED' ORDER BY bm.bp_name ASC) tt
and (/*非零售客户权限*/ (nvl(tt.retail_flag,'N') ='N' AND ( #{request.userId}=tt.created_by OR exists( select 1 from fnd_org_unit a1,fnd_employee a2,fnd_employee_assigns a3,FND_ORG_POSITION a4 where a3.employee_id=a2.employee_id and a3.unit_id=a1.unit_id and a4.position_id=a3.position_id and a4.chief_position_flag='Y' and employee_code=#{request.employeeCode} AND A1.UNIT_ID IN( select b.unit_id from sys_user_allocation a,fnd_employee_assigns b where a.user_id=tt.created_by AND a.employee_assign_id=b.employee_assign_id)) or #{request.employeeCode} in('ADMIN','HULITING'))) /*零售客户权限*/ OR (nvl(tt.retail_flag,'N') ='Y' AND ( #{request.userId}=tt.created_by or exists( select 1 from fnd_org_unit a1, sys_user_allocation a,fnd_employee_assigns b where a.user_id=#{createdBy} and a.EMPLOYEE_ASSIGN_ID=b.EMPLOYEE_ASSIGN_ID and b.unit_id =a1.unit_id and a1.unit_code != 'BUSINESS_DEPT_MANUFACTURER') )) )
