select ttt.*, CASE WHEN ttt.BP_CLASS = 'ORG' THEN '法人' WHEN ttt.BP_CLASS = 'NP' THEN '自然人' ELSE ttt.BP_CLASS END as BP_CLASS_N, (select sc.meaning from sys_code_value_b_v sc where sc.code = 'BP.BP_MASTER_ROLE' AND sc.CODE_VALUE = tttt.bp_type) description, tttt.bp_type, (select c.country_name from fnd_country c where c.country = tttt.business_area) business_area_n, 'asda' as group_company_n, 'qwew' as visit_information, (select t.description FROM hls_stat_class t WHERE t.class_usage = 'BIZ_PARTNER' AND t.enabled_flag = 'Y' and to_char(t.CLASS_ID) = tttt.economic_indu_classify) AS economic_indu_classify_n from (SELECT tt.bp_id, tt.bp_name, tt.BP_ENG_NAME, -- wm_concat(tt.description) AS description, tt.BP_CODE, tt.BP_CLASS, tt.EXTRA_NAM, to_char(tt.CREATION_DATE, 'YYYY-MM-DD') AS CREATION_DATE_STR, tt.NAME, tt.UNIT_NAME, tt.ENABLED_FLAG, tt.business_area, -- tt.business_area_n, tt.nationality_n, tt.UNIT_ID, -- tt.group_companies as group_company_n, tt.group_company_prj_amount, tt.group_company_con_amount, tt.group_company_total_amount, tt.USER_ID -- tt.visit_information, -- tt.economic_indu_classify_n FROM (SELECT DISTINCT bm.bp_id, bm.bp_name, bm.BP_ENG_NAME, bm.BP_CODE, bm.BP_CLASS, bm.EXTRA_NAM, bm.CREATION_DATE, bm.ENABLED_FLAG, TABALL.NAME, TABALL.UNIT_NAME, TABALL.USER_ID, (select fou.unit_name from hls_marketing_report_bp hmrb, hls_marketing_report hmr, fnd_org_unit fou where hmrb.bp_id = bm.bp_id and hmrb.marketing_report_id = hmr.marketing_report_id and hmr.unit_id = fou.unit_id and hmrb.creation_date = (select max(hmrb2.creation_date) from hls_marketing_report_bp hmrb2 where hmrb2.bp_id = bm.bp_id) and hmr.STATUS = 'APPROVED' and rownum=1) unit_id, CASE WHEN bm.ASSOCIATED_DIVISION IS NULL THEN 'N' ELSE bm.ASSOCIATED_DIVISION END AS ASSOCIATED_DIVISION, (select sc.meaning from sys_code_value_b_v sc where sc.code = 'BP.BP_MASTER_ROLE' AND sc.CODE_VALUE = bm.bp_type) description, bm.business_area, (select sc.meaning from sys_code_value_b_v sc where sc.code = 'HLS211_NATIONALITY' and sc.code_value = bm.nationality) nationality_n, bm.bp_type, bm.economic_indu_classify, ( select t.description FROM hls_stat_class t WHERE t.class_usage = 'BIZ_PARTNER' AND t.enabled_flag = 'Y' and to_char(t.CLASS_ID) = bm.economic_indu_classify) AS economic_indu_classify_n, (select c.country_name from fnd_country c where c.country = bm.business_area) business_area_n, 'asda' as group_company_n, '3' as group_company_prj_amount, '1' as group_company_con_amount, '2' as group_company_total_amount, 'qwew' as visit_information, bm.group_companies FROM hls_bp_master bm, (SELECT FE.NAME,SUA.USER_ID,MIN(FOU.UNIT_NAME) UNIT_NAME,SUA.COMPANY_ID FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID=FOU.UNIT_ID, (SELECT MIN(COMPANY_ID) COMPANY_ID,USER_ID FROM SYS_USER_ALLOCATION GROUP BY USER_ID ORDER BY USER_ID ASC ) SUAC, FND_EMPLOYEE FE WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.COMPANY_ID = SUAC.COMPANY_ID AND SUA.USER_ID = SUAC.USER_ID AND FE.EMPLOYEE_ID = FEA.EMPLOYEE_ID GROUP BY SUA.USER_ID,SUA.COMPANY_ID,FE.NAME ORDER BY SUA.USER_ID ASC) TABALL, ( SELECT DISTINCT hbmr.bp_id, hbmr.bp_type, hbmr.CREATION_DATE, hbmr.enabled_flag, hbmr.bp_category FROM hls_bp_master_role hbmr
