(select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'RELATED_PARTY_TYPE' and sc.code_value = hbm.RELATED_TRANSACTION_B) RELATED_TRANSACTION_B_N, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'RELATED_PARTY_TYPE' and sc.code_value = hbm.RELATED_TRANSACTION_BD) RELATED_TRANSACTION_BD_N, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'RELATED_PARTY_TYPE' and sc.code_value = hbm.RELATED_TRANSACTION_C) RELATED_TRANSACTION_C_N, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'RELATED_PARTY_TYPE' and sc.code_value = hbm.RELATED_TRANSACTION_CD) RELATED_TRANSACTION_CD_N, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'STRATEGIC_BP_TYPE' and sc.code_value = hbm.STRATEGIC_BP_TYPE) STRATEGIC_BP_TYPE_N, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'HLS.MONEY_LAUNDERING_RI_LEV' and sc.code_value = hbm.money_laundering_ri_lev) MONEY_LAUNDERING_RI_LEV_N, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'BP.LIST_TYPE' and sc.code_value = hbm.head_office_name_list) head_office_name_list_n, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'PLATFORM_RISK' and sc.code_value = hbm.PLATFORM_RISK) PLATFORM_RISK_N, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'HLS.CUSTOMER_TYPE_BP' and sc.code_value = hbm.CUSTOMER_TYPE) CUSTOMER_TYPE_N, tt.NAME, (select c.country_name from fnd_country c where c.country = hbm.BUSINESS_AREA) BUSINESS_AREA_N, hbm.group_code, hbm.FIRST_LOAN_ACCOUNT, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'SYS.YES_NO' and sc.code_value = hbm.FIRST_LOAN_ACCOUNT) FIRST_LOAN_ACCOUNT_N,
