from hls_bp_master hbm left join fnd_currency fc on hbm.register_capital_cur = fc.currency_code left join hls_business_type hbt ON hbm.bp_class = hbt.business_type and hbt.document_category = 'HLS_BP_MASTER' left join (SELECT FE.NAME,SUA.USER_ID,MIN(FOU.UNIT_NAME) UNIT_NAME,SUA.COMPANY_ID FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID=FOU.UNIT_ID, (SELECT MIN(COMPANY_ID) COMPANY_ID,USER_ID FROM SYS_USER_ALLOCATION GROUP BY USER_ID ORDER BY USER_ID ASC ) SUAC, FND_EMPLOYEE FE WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.COMPANY_ID = SUAC.COMPANY_ID AND SUA.USER_ID = SUAC.USER_ID AND FE.EMPLOYEE_ID = FEA.EMPLOYEE_ID GROUP BY SUA.USER_ID,SUA.COMPANY_ID,FE.NAME ORDER BY SUA.USER_ID ASC) tt ON tt.user_id = hbm.created_by left join hls_bp_master_role hmeb on hmeb.bp_id = hbm.bp_id
and hbm.bp_id = #{bpId}
and hbm.created_by = #{userId}
and hmeb.bp_type = #{bpType}
and hbm.bp_class = #{bpClass}

select hbm.bp_id, hbm.bp_name, hbm.register_cert_num, a.BANK_ACCOUNT_NUM from hls_bp_master hbm,HLS_BP_MASTER_BANK_ACCOUNT a where a.BP_Id=hbm.BP_ID and a.ebs_business_code is null
and hbm.bp_name = #{bpName}
and hbm.register_cert_num = #{registerCertNum}
and rownum <10

select hbm.BP_ID,hbm.BP_CODE,hbm.BP_NAME,hbm.BP_CLASS,hbm.EXTRA_NAM,hbm.enabled_flag,hbt.description bpClassN,hbpt.description bpTypeN ,su.DESCRIPTION ownerUserIdN, hbm.bp_category, (select hbc.description from hls_bp_category hbc where hbc.bp_category=hbm.bp_category) bp_category_n, hbm.bp_approve_status, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'HLS_WFL_STATUS' AND v.code_value = nvl(hbm.bp_approve_status, 'NEW')) bp_approve_status_n, (select distinct fou.unit_name from sys_user_allocation su,fnd_employee_assigns fea,fnd_org_unit fou where su.user_id = hbm.owner_user_id and su.employee_assign_id = fea.employee_assign_id and fou.unit_id = fea.unit_id and fea.primary_position_flag = 'Y' and su.enabled_flag = 'Y' and fea.enabled_flag = 'Y') unit_id_n, to_char(hbm.creation_date,'yyyy-mm-dd') creation_date_n from hls_bp_master hbm left join hls_business_type hbt on hbm.bp_class = hbt.business_type and hbt.document_category = 'HLS_BP_MASTER' left join hls_bp_type hbpt on hbm.bp_type = hbpt.bp_type left join sys_user su on hbm.owner_user_id = su.user_id
exists (select 1 from hls_bp_master_role hbmr where hbmr.bp_id = hbm.bp_id and hbmr.bp_category in ('VENDER', 'DEALER')) AND hbm.bp_category!='HLS_BP_CREDIT' AND hbm.bp_category != 'MANUFACTURER' AND ((#{userId} IN (SELECT SUA.USER_ID FROM FND_ORG_POSITION FOP, FND_EMPLOYEE_ASSIGNS FEA, SYS_USER_ALLOCATION SUA WHERE FOP.POSITION_CODE = 'DEPT0230_POSITION010' AND FEA.POSITION_ID = FOP.POSITION_ID AND FEA.ENABLED_FLAG = 'Y' AND FEA.PRIMARY_POSITION_FLAG = 'Y' AND SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID AND SUA.ENABLED_FLAG = 'Y') AND HBM.BP_CATEGORY NOT IN ('MANUFACTURER','VENDER') ) OR (#{userId} IN (SELECT SUA.USER_ID FROM FND_ORG_POSITION FOP, FND_EMPLOYEE_ASSIGNS FEA, SYS_USER_ALLOCATION SUA WHERE FOP.POSITION_CODE = 'DEPT0230_POSITION020' AND FEA.POSITION_ID = FOP.POSITION_ID AND FEA.ENABLED_FLAG = 'Y' AND FEA.PRIMARY_POSITION_FLAG = 'Y' AND SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID AND SUA.ENABLED_FLAG = 'Y') AND HBM.BP_CATEGORY NOT IN ('MANUFACTURER','VENDER','DEALER') ) OR (#{userId} IN (SELECT SUA.USER_ID FROM FND_ORG_POSITION FOP, FND_EMPLOYEE_ASSIGNS FEA, SYS_USER_ALLOCATION SUA WHERE FOP.POSITION_CODE = 'DEPT0230_POSITION030' AND FEA.POSITION_ID = FOP.POSITION_ID AND FEA.ENABLED_FLAG = 'Y' AND FEA.PRIMARY_POSITION_FLAG = 'Y' AND SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID AND SUA.ENABLED_FLAG = 'Y') AND HBM.BP_CATEGORY NOT IN ('MANUFACTURER','MANAGEMENT_COMPANY') or #{userId} NOT IN (SELECT SUA.USER_ID FROM FND_ORG_POSITION FOP, FND_EMPLOYEE_ASSIGNS FEA, SYS_USER_ALLOCATION SUA WHERE FOP.POSITION_CODE IN ('DEPT0230_POSITION030','DEPT0230_POSITION020','DEPT0230_POSITION010') AND FEA.POSITION_ID = FOP.POSITION_ID AND FEA.ENABLED_FLAG = 'Y' AND FEA.PRIMARY_POSITION_FLAG = 'Y' AND SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID AND SUA.ENABLED_FLAG = 'Y')))
and hbm.bp_code >= #{bpCodeFromN}
and hbm.bp_code <= #{bpCodeToN}
and hbm.bp_code = #{bpCode}
and hbm.bp_name like concat('%', concat(#{bpName,jdbcType=VARCHAR}, '%'))
and hbm.bp_class = #{bpClass}
and hbm.bp_type like concat('%', concat(#{bpType,jdbcType=VARCHAR}, '%'))
and hbm.extra_nam like concat('%', concat(#{extraNam,jdbcType=VARCHAR}, '%'))
and hbm.enabled_flag = #{enabledFlag}
and hbm.owner_user_id = #{ownerUserId}
and (select fou.unit_name from sys_user_allocation su,fnd_employee_assigns fea,fnd_org_unit fou where su.user_id = hbm.owner_user_id and su.employee_assign_id = fea.employee_assign_id and fou.unit_id = fea.unit_id and fea.primary_position_flag = 'Y' and su.enabled_flag = 'Y' and fea.enabled_flag = 'Y') like concat('%', concat(#{unitName,jdbcType=VARCHAR}, '%'))
and hbm.bp_approve_status = #{bpApproveStatus}
order by hbm.bp_id desc
